function CreateFakeDom() {
  class FakeElement {
    constructor(tag) {
      this.tagName = tag.toUpperCase();
      this.nodeName = this.tagName;
      this.className = "";
      this.classList = {
        add: (...names) => {
          const existing = this.className ? this.className.split(/\s+/) : [];
          for (const name of names) {
            if (!existing.includes(name)) {
              existing.push(name);
            }
          }
          this.className = existing.join(" ");
        },
        remove: (...names) => {
          const existing = this.className ? this.className.split(/\s+/) : [];
          this.className = existing.filter((name) => !names.includes(name)).join(" ");
        },
        contains: (name) => {
          const existing = this.className ? this.className.split(/\s+/) : [];
          return existing.includes(name);
        },
      };
      this.dataset = {};
      this.style = {};
      this.children = [];
      this.childNodes = this.children;
      this.parentNode = null;
      this._textContent = "";
      this.innerHTML = "";
      this.type = "";
      this.scrollHeight = 0;
      this.scrollTop = 0;
      this.clientHeight = 0;
      this._listeners = {};
    }

    get textContent() {
      if (this.children.length === 0) {
        return this._textContent;
      }
      return this.children.map((child) => child.textContent).join("");
    }

    set textContent(value) {
      this._textContent = value != null ? String(value) : "";
      this.children = [];
      this.innerHTML = "";
    }

    appendChild(child) {
      if (child.parentNode) {
        child.parentNode.removeChild(child);
      }
      child.parentNode = this;
      this.children.push(child);
      if (
        this.className &&
        this.className.includes("agui-chat-transcript")
      ) {
        this.scrollHeight = Math.max(this.scrollHeight, this.children.length * 500);
      }
      return child;
    }

    removeChild(child) {
      const index = this.children.indexOf(child);
      if (index >= 0) {
        this.children.splice(index, 1);
        child.parentNode = null;
      }
      return child;
    }

    addEventListener(type, handler) {
      this._listeners[type] = handler;
    }

    removeEventListener(type) {
      delete this._listeners[type];
    }

    click() {
      if (this._listeners.click) {
        this._listeners.click();
      }
    }

    querySelector(selector) {
      if (selector.startsWith(".")) {
        const className = selector.slice(1);
        const stack = [...this.children];
        while (stack.length) {
          const node = stack.shift();
          if (node.className && node.className.split(/\s+/).includes(className)) {
            return node;
          }
          stack.push(...node.children);
        }
      }
      return null;
    }

    querySelectorAll(selector) {
      const results = [];
      if (selector.startsWith(".")) {
        const className = selector.slice(1);
        const stack = [...this.children];
        while (stack.length) {
          const node = stack.shift();
          if (node.className && node.className.split(/\s+/).includes(className)) {
            results.push(node);
          }
          stack.push(...node.children);
        }
      }
      return results;
    }
  }

  function createElement(tag) {
    return new FakeElement(tag);
  }

  return { createElement, FakeElement };
}

const moduleDom = CreateFakeDom();
const document = { createElement: moduleDom.createElement };

function LoadChatView(options) {
  const opts = options || {};
  const fakeDom = CreateFakeDom();
  const pendingFrames = [];

  const source = fs.readFileSync(aguiChatPath, "utf8");
  const context = {
    console,
    setTimeout,
    clearTimeout,
    document: {
      createElement: fakeDom.createElement,
    },
    requestAnimationFrame(callback) {
      pendingFrames.push(callback);
      return pendingFrames.length;
    },
    cancelAnimationFrame(id) {
      pendingFrames[id - 1] = null;
    },
    flushAnimationFrames() {
      while (pendingFrames.length) {
        const callback = pendingFrames.shift();
        if (callback) {
          callback();
        }
      }
    },
    WebSocket:
      opts.WebSocket ||
      class FakeWebSocket {
        constructor(url) {
          this.url = url;
          this.readyState = 0;
          this.CONNECTING = 0;
          this.OPEN = 1;
          this.CLOSING = 2;
          this.CLOSED = 3;
        }

        addEventListener() {}

        removeEventListener() {}

        close() {
          this.readyState = 3;
        }
      },
  };
  context.globalThis = context;
  context.window = context;
  vm.createContext(context);
  vm.runInContext(source, context);
  context.ChatView._flushFrames = context.flushAnimationFrames;
  context.ChatView._FakeElement = fakeDom.FakeElement;
  return context.ChatView;
}

