        });
      });
      item.appendChild(button);
      list.appendChild(item);
    }
  }

  function PopulateModelSelect() {
    modelSelect.textContent = "";
    for (const model of models) {
      const option = document.createElement("option");
      option.value = model.provider + ":" + model.id;
      option.textContent =
