    .then(function (results) {
      models = results[0].models || [];
      PopulateModelSelect();
      RenderSessionRows(results[1].sessions || []);
    })
    .catch(function (error) {
      errorNode.textContent = error.message || "Failed to load sessions";
    });
}

function BuildWebSocketUrl(pile, sessionId, after) {
  const params = new URLSearchParams();
  params.set("p", pile);
  params.set("session", sessionId);
  params.set("client", GetClientId());
  if (after != null && after > 0) {
    params.set("after", String(after));
  }

  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  return (
    protocol +
    "//" +
    window.location.host +
    "/ws/chat?" +
    params.toString()
  );
}

function CreateEnvelope(kind, pile, sessionId, payload) {
  return {
    v: 1,
    kind: kind,
    id: GenerateId(),
    pile: pile,
    sessionId: sessionId,
    timestamp: new Date().toISOString(),
    payload: payload,
  };
}

function RenderChatScreen(app, route) {
  app.textContent = "";
  if (!window.ChatView) {
    const missing = CreateElement("p", "sheaf-chat-error");
    missing.textContent = "Chat renderer failed to load.";
    app.appendChild(missing);
    return;
  }

  const touchLayout = IsTouchLayout();
  app.classList.toggle("sheaf-chat-touch", touchLayout);
  app.classList.toggle("sheaf-chat-desktop", !touchLayout);

  const screen = CreateElement("div", "sheaf-chat-screen sheaf-chat-chat-layout");
  const header = CreateElement("header", "sheaf-chat-header");
  const back = CreateElement("button", "sheaf-chat-back");
  back.type = "button";
  back.textContent = "Back";
  back.addEventListener("click", function () {
    NavigateTo({ screen: "sessions", pile: route.pile });
  });
  header.appendChild(back);

  const title = CreateElement("h1", "sheaf-chat-header-title");
  title.textContent = route.sessionId;
  header.appendChild(title);
  screen.appendChild(header);

  const statusRow = CreateElement("div", "sheaf-chat-chat-status");
  const connectionLabel = CreateElement("span");
  connectionLabel.textContent = "Connecting…";
  statusRow.appendChild(connectionLabel);

  const modelSelect = CreateElement("select", "sheaf-chat-model-select");
  statusRow.appendChild(modelSelect);
  screen.appendChild(statusRow);

  const chatMain = CreateElement("div", "sheaf-chat-chat-main");
  const chatContainer = CreateElement("div");
  chatMain.appendChild(chatContainer);
  screen.appendChild(chatMain);

  const composer = CreateElement("div", "sheaf-chat-composer");
  const textarea = CreateElement("textarea", "sheaf-chat-textarea");
  textarea.rows = 1;
  textarea.placeholder = "Message the agent…";
  const sendButton = CreateElement(
    "button",
    "sheaf-chat-button sheaf-chat-button--primary sheaf-chat-send"
  );
  sendButton.type = "button";
  sendButton.textContent = "Send";
  composer.appendChild(textarea);
  composer.appendChild(sendButton);
  screen.appendChild(composer);
  app.appendChild(screen);

  let socket = null;
  let chatHandle = null;
  let destroyed = false;
  let connected = false;
  let lastSequence = 0;
  let oldestSequence = null;
  let hasMoreBefore = false;
  let historyLoading = false;
  let models = [];
  let activeModel = null;
  let reconnectTimer = null;
  let intentionalClose = false;
  const outboundQueue = [];

  function UpdateComposerState() {
    const queuedCount = outboundQueue.length;
    composer.classList.toggle("sheaf-chat-composer--disconnected", !connected);
    composer.classList.toggle("sheaf-chat-composer--queued", queuedCount > 0);
    textarea.disabled = false;
    sendButton.disabled = !connected && queuedCount === 0;
    if (chatHandle) {
      window.ChatView.setConnectionState(chatHandle, {
        connected: connected,
        queuedCount: queuedCount,
        label: connected ? null : "Disconnected",
      });
    }
  }

  function ResizeTextarea() {
    textarea.style.height = "auto";
    const maxHeight = 200;

  const maxHeight = 200;
  textarea.style.height =
    Math.min(textarea.scrollHeight, maxHeight) + "px";
}

function PopulateModels() {
  modelSelect.textContent = "";
  for (const model of models) {
    const option = document.createElement("option");
    option.value = model.provider + ":" + model.id;
    const selected =
      activeModel &&
      activeModel.provider === model.provider &&
      activeModel.id === model.id;
    option.selected = selected;
    option.textContent =
      (model.displayName || model.id) +
      (model.available === false ? " (unavailable)" : "");
    option.disabled = model.available === false;
    modelSelect.appendChild(option);
  }
}

function UpdateStatusText() {
  const modelText =
    activeModel != null
      ? activeModel.provider + "/" + activeModel.id
      : "model unknown";
  connectionLabel.innerHTML =
    "<strong>" +
    (connected ? "Connected" : "Disconnected") +
    "</strong> · " +
    modelText;
}

function SendEnvelope(envelope) {
  if (!socket || socket.readyState !== WebSocket.OPEN) {
    return false;
  }
  socket.send(JSON.stringify(envelope));
  return true;
}

function FlushQueue() {
  if (!connected) {
    return;
  }
  while (outboundQueue.length > 0) {
    const item = outboundQueue[0];
    if (!SendEnvelope(item)) {
      break;
    }
    outboundQueue.shift();
  }
  UpdateComposerState();
}

function QueueOrSend(envelope) {
  if (SendEnvelope(envelope)) {
    return;
  }
  outboundQueue.push(envelope);
  UpdateComposerState();
}

function SendAck(sequence) {
  if (sequence == null || sequence <= 0) {
    return;
  }
  SendEnvelope(
    CreateEnvelope("client.ack", route.pile, route.sessionId, {
      sequence: sequence,
    })
  );
}

function RequestHistory(options) {
  const payload = {
    limit: options.limit || x_HistoryPageLimit,
    prefer: "snapshots",
  };
  if (options.before != null) {
    payload.before = options.before;
  }
  if (options.after != null) {
    payload.after = options.after;
  }
  const envelope = CreateEnvelope(
    "client.history_request",
    route.pile,
    route.sessionId,
    payload
  );
  if (options.before != null) {
    historyLoading = true;
  }
  QueueOrSend(envelope);
}

function HandleHistoryPage(payload) {
  historyLoading = false;
  if (!payload) {
    return;
  }

  if (payload.oldestSequence != null) {
    oldestSequence = payload.oldestSequence;
  }
  if (payload.hasMoreBefore != null) {
    hasMoreBefore = payload.hasMoreBefore === true;
  }

  const messages = Array.isArray(payload.messages) ? payload.messages : [];
  if (messages.length > 0 && chatHandle) {
    window.ChatView.prependHistory(chatHandle, messages);
  }

  const events = Array.isArray(payload.events) ? payload.events : [];
  for (const event of events) {
    if (event && chatHandle) {
      window.ChatView.appendAguiEvent(chatHandle, event);
    }
  }
}

function HandleServerEnvelope(envelope) {
  if (!envelope || typeof envelope !== "object") {
    return;
  }

  if (envelope.sequence != null && envelope.sequence > lastSequence) {
    lastSequence = envelope.sequence;
    SendAck(envelope.sequence);
  }

  const kind = envelope.kind;
  const payload = envelope.payload;

  if (kind === "server.hello") {
    if (payload && Array.isArray(payload.models)) {
      models = payload.models;
    }
    if (payload && payload.activeModel) {
      activeModel = payload.activeModel;
    }
    if (payload && payload.manifest && payload.manifest.chatName) {
      title.textContent = payload.manifest.chatName;
    }
    if (payload && payload.latestSequence != null) {
      lastSequence = Math.max(lastSequence, payload.latestSequence);
    }
    if (payload && payload.historyWindow) {
      oldestSequence = payload.historyWindow.oldestSequence;
      hasMoreBefore =
        payload.historyWindow.oldestSequence != null &&
        payload.historyWindow.oldestSequence > 1;
    }
    PopulateModels();
    UpdateStatusText();
    RequestHistory({ limit: x_InitialHistoryLimit });
    return;
  }

  if (kind === "history.page") {
    HandleHistoryPage(payload);
    return;
  }

  if (kind === "agui.event" && payload) {
    if (chatHandle) {
      window.ChatView.appendAguiEvent(chatHandle, payload);
    }
    return;
  }

  if (kind === "chat.user_message" && payload) {
    const messageId = payload.messageId || GenerateId();
    if (chatHandle) {
      window.ChatView.appendAguiEvent(chatHandle, {
        type: "TEXT_MESSAGE_START",
        messageId: messageId,
        role: "user",
      });
      window.ChatView.appendAguiEvent(chatHandle, {
        type: "TEXT_MESSAGE_CONTENT",
        messageId: messageId,
        delta: payload.text != null ? String(payload.text) : "",
      });
      window.ChatView.appendAguiEvent(chatHandle, {
        type: "TEXT_MESSAGE_END",
        messageId: messageId,
      });
    }
    return;
  }

  if (kind === "model.changed" && payload && payload.model) {
    activeModel = payload.model;
    PopulateModels();
    UpdateStatusText();
    return;
  }

  if (kind === "session.updated" && payload && payload.manifest) {
    if (payload.manifest.chatName) {
      title.textContent = payload.manifest.chatName;
    }
    return;
  }

  if (kind === "agent.status" && payload && payload.state) {
    connectionLabel.innerHTML =
      "<strong>" +
      (connected ? "Connected" : "Disconnected") +
      "</strong> · agent " +
      String(payload.state);
    return;
  }

  if (kind === "server.caught_up") {
    if (chatHandle) {
      window.ChatView.setCaughtUp(chatHandle, true);
    }
    return;
  }

  if (kind === "server.error" && payload) {
    connectionLabel.textContent = String(payload.message || "Server error");
  }
}

function Connect() {
  if (destroyed) {
    return;
  }

  intentionalClose = false;
  connected = false;
  UpdateComposerState();
  UpdateStatusText();

  const wsUrl = BuildWebSocketUrl(route.pile, route.sessionId, lastSequence);
  socket = new WebSocket(wsUrl);

  socket.addEventListener("open", function () {
    connected = true;
    UpdateComposerState();
    UpdateStatusText();
    FlushQueue();
    SendEnvelope(
      CreateEnvelope("client.hello", route.pile, route.sessionId, {
        supportsSnapshots: true,
        supportsLazyHistory: true,
        lastSeenSequence: lastSequence,
      })
    );
  });

  socket.addEventListener("message", function (event) {
    let envelope;
    try {

        try {
          envelope = JSON.parse(event.data);
        } catch (_error) {
          return;
        }
        HandleServerEnvelope(envelope);
      });

      socket.addEventListener("close", function () {
        connected = false;
        UpdateComposerState();
        UpdateStatusText();
        if (!destroyed && !intentionalClose) {
          reconnectTimer = window.setTimeout(function () {
            Connect();
          }, x_ReconnectDelayMs);
        }
      });

      socket.addEventListener("error", function () {
        connected = false;
        UpdateComposerState();
        UpdateStatusText();
      });
    }

    function DestroyChat() {
      destroyed = true;
      intentionalClose = true;
      if (reconnectTimer != null) {
        clearTimeout(reconnectTimer);
        reconnectTimer = null;
      }
      if (socket) {
        socket.close();
        socket = null;
      }
      if (chatHandle) {
        window.ChatView.destroy(chatHandle);
        chatHandle = null;
      }
    }

    chatHandle = window.ChatView.create(chatContainer, {
      onScrollNearTop: function () {
        if (historyLoading || !hasMoreBefore || oldestSequence == null) {
          return;
        }
        RequestHistory({ before: oldestSequence, limit: x_HistoryPageLimit });
      },
    });
    UpdateComposerState();

    modelSelect.addEventListener("change", function () {
      const parts = modelSelect.value.split(":");
      if (parts.length !== 2) {
        return;
      }
      QueueOrSend(
        CreateEnvelope("client.model_select", route.pile, route.sessionId, {
          provider: parts[0],
          id: parts[1],
          applyTo: "next_turn",
        })
      );
    });

    function SubmitMessage() {
      const text = textarea.value.trim();
      if (!text) {
        return;
      }

      const messageId = GenerateId();
      QueueOrSend(
        CreateEnvelope("client.user_message", route.pile, route.sessionId, {
          messageId: messageId,
          text: text,
          attachments: [],
          steer: true,
        })
      );
      textarea.value = "";
      ResizeTextarea();
      UpdateComposerState();
    }

    sendButton.addEventListener("click", SubmitMessage);

    textarea.addEventListener("input", ResizeTextarea);

    textarea.addEventListener("keydown", function (event) {
      if (event.key !== "Enter") {
        return;
      }

      if (touchLayout) {
        return;
      }

      if (event.shiftKey) {
        return;
      }

      event.preventDefault();
      SubmitMessage();
    });

    window.addEventListener(
      "pagehide",
      function () {
        DestroyChat();
      },
      { once: true }
    );

    Connect();

    return DestroyChat;
  }

  function Render(route) {
    const app = document.getElementById("app");
    if (!app) {
      return null;
    }

    if (route.screen === "piles") {
      RenderPilesScreen(app, route);
      return null;
    }

    if (route.screen === "sessions") {
      RenderSessionsScreen(app, route);
      return null;
    }

    if (route.screen === "chat") {
      return RenderChatScreen(app, route);
    }

    RenderPilesScreen(app, route);
    return null;
  }

  function Boot() {
    let destroyChat = null;

    function OnRouteChange() {
      if (destroyChat) {
        destroyChat();
        destroyChat = null;
      }
      const route = ParseRoute();
      destroyChat = Render(route);
    }

    window.addEventListener("hashchange", OnRouteChange);
    window.addEventListener("popstate", OnRouteChange);
    OnRouteChange();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", Boot);
  } else {
    Boot();
  }

  const SheafChatApp = {
    _test: {
      parseRoute: ParseRoute,
      buildWebSocketUrl: BuildWebSocketUrl,
      createEnvelope: CreateEnvelope,
      isTouchLayout: IsTouchLayout,
    },
  };

  if (typeof globalThis !== "undefined") {
    globalThis.SheafChatApp = SheafChatApp;
  }
  if (typeof window !== "undefined") {
    window.SheafChatApp = SheafChatApp;
  }
})();

/**
 * AG UI event reducer and ChatView API for streaming chat transcripts.
 * Framework-free; attaches window.ChatView / globalThis.ChatView.
 */
(function () {
  "use strict";

  function CreateChatState() {
    return {
      messages: new Map(),
      messageOrder: [],
      openTextMessages: new Set(),
      openToolCalls: new Map(),
      openReasoning: new Set(),
      runs: new Map(),
      activeSteps: new Map(),
      caughtUp: false,
      eventCount: 0,
      status: { kind: "loading", message: null },
    };
  }

  function SynthesizeId(state, eventType) {
    return `${eventType}:${state.eventCount}`;
  }

  function CreateChatMessage(id, role, options) {
    const opts = options || {};
    return {
      id: id,
      role: role,
      content: opts.content != null ? String(opts.content) : "",
      toolCalls: opts.toolCalls ? opts.toolCalls.slice() : [],
      toolCallId: opts.toolCallId != null ? opts.toolCallId : null,
      isStreaming: opts.isStreaming === true,
      timestamp: opts.timestamp != null ? opts.timestamp : null,
      activityType: opts.activityType != null ? opts.activityType : null,
    };
  }

  function AddMessage(state, message) {
    if (!state.messages.has(message.id)) {
      state.messageOrder.push(message.id);
    }
    state.messages.set(message.id, message);
    return message;
  }

  function AppendSystemMessage(state, content, id) {
    const messageId = id || SynthesizeId(state, "system");
    return AddMessage(
      state,
      CreateChatMessage(messageId, "system", { content: content })
    );
  }

  function FindToolCallInfo(state, toolCallId) {
    for (const messageId of state.messageOrder) {
      const message = state.messages.get(messageId);
      if (!message || message.role !== "assistant") {
        continue;
      }
      for (const toolCall of message.toolCalls) {
        if (toolCall.id === toolCallId) {
          return toolCall;
        }
      }
    }
    return null;
  }

  function RecomputeStatus(state) {
    if (state.status.kind === "error") {
      return;
    }
    if (!state.caughtUp) {
      state.status = { kind: "loading", message: null };
      return;
    }
    let hasRunning = false;
    for (const run of state.runs.values()) {
      if (run.status === "running") {
        hasRunning = true;
        break;
      }
    }
    if (hasRunning) {
      state.status = { kind: "live", message: null };
    } else {
      state.status = { kind: "complete", message: null };
    }
  }

  function CloseOpenStreams(state) {
    for (const messageId of Array.from(state.openTextMessages)) {
      const message = state.messages.get(messageId);
      if (message) {
        message.isStreaming = false;
      }
      state.openTextMessages.delete(messageId);
    }

    for (const toolCallId of Array.from(state.openToolCalls.keys())) {
      const openTool = state.openToolCalls.get(toolCallId);
      const toolInfo = FindToolCallInfo(state, toolCallId);
      if (toolInfo) {
        toolInfo.isOpen = false;
      }
      state.openToolCalls.delete(toolCallId);
      if (openTool) {
        openTool.argsBuffer = toolInfo ? toolInfo.args : openTool.argsBuffer;
      }
    }

    for (const messageId of Array.from(state.openReasoning)) {
      const message = state.messages.get(messageId);
      if (message) {
        message.isStreaming = false;
      }
      state.openReasoning.delete(messageId);
    }
  }

  function SnapshotMessageToChatMessage(snapshotMessage) {
    const role = snapshotMessage.role || "activity";
    const message = CreateChatMessage(String(snapshotMessage.id), role, {
      content:
        snapshotMessage.content != null ? String(snapshotMessage.content) : "",
      timestamp: snapshotMessage.timestamp != null ? snapshotMessage.timestamp : null,
      activityType:
        snapshotMessage.activityType != null
          ? snapshotMessage.activityType
          : null,
      toolCallId:
        snapshotMessage.toolCallId != null ? snapshotMessage.toolCallId : null,
    });

    if (Array.isArray(snapshotMessage.toolCalls)) {
      message.toolCalls = snapshotMessage.toolCalls.map(function (toolCall) {
        return {
          id: String(toolCall.id || toolCall.toolCallId || ""),
          name: String(toolCall.name || toolCall.toolCallName || ""),
          args: toolCall.arguments != null ? String(toolCall.arguments) : toolCall.args != null ? String(toolCall.args) : "",
          result: toolCall.result != null ? String(toolCall.result) : null,
          isOpen: false,
        };
      });
    }

    return message;
  }

  function ParseActivityContent(message) {
    if (!message || !message.content) {
      return {};
    }
    try {
      const parsed = JSON.parse(message.content);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return parsed;
      }
    } catch (_error) {
      //
    }
    return { text: message.content };
  }

  function StringifyActivityContent(value) {
    if (typeof value === "string") {
      return value;
    }
    try {
      return JSON.stringify(value);
    } catch (_error) {
      return String(value);
    }
  }

  function DecodeJsonPointerSegment(segment) {
    return segment.replace(/~1/g, "/").replace(/~0/g, "~");
  }

  function ParseJsonPointer(path) {
    if (typeof path !== "string" || path === "" || path === "/") {
      return [];
    }
    if (path.charAt(0) !== "/") {
      return null;
    }
    return path
      .slice(1)
      .split("/")
      .map(DecodeJsonPointerSegment);
  }

  function ResolvePatchParent(root, tokens) {
    if (!tokens || tokens.length === 0) {
      return { parent: null, key: null, valid: false };
    }
    let current = root;
    for (let index = 0; index < tokens.length - 1; index += 1) {
      const token = tokens[index];
      if (current == null || typeof current !== "object") {
        return { parent: null, key: null, valid: false };
      }
      current = current[token];
    }
    const lastToken = tokens[tokens.length - 1];
    if (current == null || typeof current !== "object") {
      return { parent: null, key: null, valid: false };
    }
    return { parent: current, key: lastToken, valid: true };
  }

  function ApplyJsonPatch(document, patch) {
    if (!Array.isArray(patch)) {
      return null;
    }

    let nextDocument;

  let nextDocument;
  try {
    nextDocument = JSON.parse(JSON.stringify(document));
  } catch (_error) {
    return null;
  }

  for (const operation of patch) {
    if (!operation || typeof operation !== "object") {
      return null;
    }

    const op = operation.op;
    const pathTokens = ParseJsonPointer(operation.path);
    if (pathTokens === null) {
      return null;
    }

    if (op === "add" || op === "replace") {
      if (pathTokens.length === 0) {
        if (op === "replace") {
          nextDocument = operation.value;
        } else {
          return null;
        }
        continue;
      }

      const resolved = ResolvePatchParent(nextDocument, pathTokens);
      if (!resolved.valid) {
        return null;
      }

      if (Array.isArray(resolved.parent) && resolved.key === "-") {
        if (op !== "add") {
          return null;
        }
        resolved.parent.push(operation.value);
      } else {
        resolved.parent[resolved.key] = operation.value;
      }
    } else if (op === "remove") {
      if (pathTokens.length === 0) {
        return null;
      }
      const resolved = ResolvePatchParent(nextDocument, pathTokens);
      if (!resolved.valid) {
        return null;
      }
      if (Array.isArray(resolved.parent)) {
        const index = Number(resolved.key);
        if (!Number.isInteger(index) || index < 0 || index >= resolved.parent.length) {
          return null;
        }
        resolved.parent.splice(index, 1);
      } else {
        delete resolved.parent[resolved.key];
      }
    } else {
      return null;
    }
  }

  return nextDocument;
}

function CustomDisplayText(event) {
  if (event.name === "provider.text") {
    const value = event.value;
    if (value && typeof value === "object") {
      if (value.text != null) {
        return String(value.text);
      }
    }
    if (event.text != null) {
      return String(event.text);
    }
    return "";
  }
  return String(event.name || "custom");
}

function ReduceAguiEvent(state, event) {
  if (!event || typeof event !== "object") {
    return state;
  }

  state.eventCount += 1;
  const eventType = event.type;

  switch (eventType) {
    case "RUN_STARTED": {
      const runId = event.runId ? String(event.runId) : SynthesizeId(state, "RUN_STARTED");
      state.runs.set(runId, {
        runId: runId,
        threadId: event.threadId != null ? String(event.threadId) : runId,
        status: "running",
      });
      RecomputeStatus(state);
      break;
    }

    case "RUN_FINISHED": {
      const runId = event.runId ? String(event.runId) : null;
      if (runId && state.runs.has(runId)) {
        const run = state.runs.get(runId);
        run.status = "finished";
      }
      CloseOpenStreams(state);
      RecomputeStatus(state);
      break;
    }

    case "RUN_ERROR": {
      const runId = event.runId ? String(event.runId) : null;
      if (runId && state.runs.has(runId)) {
        const run = state.runs.get(runId);
        run.status = "error";
      }
      const errorText = event.message != null ? String(event.message) : "Run error";
      AppendSystemMessage(
        state,
        errorText,
        runId ? `error:${runId}` : SynthesizeId(state, "RUN_ERROR")
      );
      state.status = { kind: "error", message: errorText };
      break;
    }

    case "STEP_STARTED": {
      const stepName = event.stepName ? String(event.stepName) : SynthesizeId(state, "STEP_STARTED");
      state.activeSteps.set(stepName, {
        stepName: stepName,
        startTimestamp: event.timestamp != null ? event.timestamp : null,
      });
      break;
    }

    case "STEP_FINISHED": {
      const stepName = event.stepName ? String(event.stepName) : null;
      if (stepName) {
        state.activeSteps.delete(stepName);
      }
      break;
    }

    case "TEXT_MESSAGE_START": {
      const messageId = event.messageId
        ? String(event.messageId)
        : SynthesizeId(state, "TEXT_MESSAGE_START");
      const role = event.role ? String(event.role) : "assistant";
      AddMessage(
        state,
        CreateChatMessage(messageId, role, {
          isStreaming: true,
          timestamp: event.timestamp != null ? event.timestamp : null,
        })
      );
      state.openTextMessages.add(messageId);
      break;
    }

    case "TEXT_MESSAGE_CONTENT": {
      const messageId = event.messageId ? String(event.messageId) : null;
      if (!messageId) {
        break;
      }
      let message = state.messages.get(messageId);
      if (!message) {
        message = AddMessage(
